func olsLine(startIndex int, values []float64) (slope, intercept float64) {
	n := len(values)
	if n == 0 {
		return 0, 0
	}
	var sumX, sumY, sumXY, sumX2 float64
	for i, y := range values {
		x := float64(startIndex + i)
		sumX += x
		sumY += y
		sumXY += x * y
		sumX2 += x * x
	}

	denom := float64(n)*sumX2 - sumX*sumX
	if denom == 0 {
		slope = 0
		intercept = values[0]
		return
	}
	slope = (float64(n)*sumXY - sumX*sumY) / denom
	intercept = (sumY - slope*sumX) / float64(n)
	return
}

func predictLine(slope, intercept float64, startIndex, steps int) []float64 {
	predictions := make([]float64, steps)
	for i := 0; i < steps; i++ {
		predictions[i] = slope*float64(startIndex+i) + intercept
	}
	return predictions
}

func trendFromSlope(slope float64) string {
	r := roundHalfUp4(slope)
	if r > 0 {
		return "increasing"
	}
	if r < 0 {
		return "decreasing"
	}
	return "stable"
}

func overallTrend(a, b string) string {
	if a == "increasing" && b == "increasing" {
		return "increasing"
	}
	if a == "decreasing" && b == "decreasing" {
		return "decreasing"
	}
	if a == "increasing" || b == "increasing" {
		if a == "decreasing" || b == "decreasing" {
			return "mixed"
		}
		return "increasing"
	}
	if a == "decreasing" || b == "decreasing" {
		return "decreasing"
	}
	return "stable"
}

func alertLevelFromSlopes(risks, threats []float64, riskSlope, threatSlope float64) string {
	riskMean := meanOfValues(risks)
	threatMean := meanOfValues(threats)

	maxRatio := 0.0
	if riskSlope > 0 {
		ratio := riskSlope / math.Max(riskMean, 1.0)
		if ratio > maxRatio {
			maxRatio = ratio
		}
	}
	if threatSlope > 0 {
		ratio := threatSlope / math.Max(threatMean, 1.0)
		if ratio > maxRatio {
			maxRatio = ratio
		}
	}

	if maxRatio >= 0.5 {
		return "critical"
	}
	if maxRatio >= 0.2 {
		return "warning"
	}
	return "normal"
}

func meanOfValues(values []float64) float64 {
	if len(values) == 0 {
		return 0
	}
	var sum float64
	for _, v := range values {
		sum += v
	}
	return sum / float64(len(values))
}

func roundAll4(values []float64) []json.Number {
	out := make([]json.Number, len(values))
	for i, v := range values {
		out[i] = json.Number(format4(v))
	}
	return out
}
